184	+/* ============================ Lái xe máy: phần HUD riêng (xi nhan, góc nhìn, còi, về làn, gợi ý phím, nhắc khi kẹt) + bộ chuyển cảm ứng ============================
185	+   Spec D-040 §10. Đồng hồ số km/h và bản đồ nhỏ là của ô tô (drive/hud.ts) dùng nguyên; phần này chỉ thêm các phần tử bk* trong #drHud (index.html).
186	+   - #bkSigL / #bkSigR: đèn xi nhan (lớp 'on' khi đang bật, 'lit' ở nửa chu kỳ sáng, cùng nhịp đèn trên xe: CONFIG.bike.model.sigHz); bấm được (cảm ứng và chuột).
187	+   - #bkStuck: "Bị kẹt? Bấm R" khi s.stuck ≥ hud.stuckS (lớp 'show'); cùng lúc #bkReset sáng lên (lớp 'hot'), trên cảm ứng chỉ có nút sáng (chữ nói phím R).
188	+   - #bkHint: gợi ý phím (thay #drHint của ô tô, CSS ẩn #drHint khi body.bike), tự ẩn sau hud.hintMs.
189	+   - bkHudUpdate mỗi khung chỉ ghi DOM khi xi nhan / pha nhấp nháy (khi đang bật) / trạng thái kẹt đổi (D-018: không ghi lớp thừa, không cấp phát).
190	+   - bkTouchMerge: cảm ứng dùng nguyên drive/touch.ts (đọc vào DrInput); chép đầu vào phím BkInput sang DrInput, cho touch đọc gộp, chép lại; ô hand ⇒ hard.
191	+   Module không đụng DOM lúc import (test đơn vị chạy trong Node, phần tử giả qua bkHudBind). */
192	+import { CONFIG } from '../../config';
193	+import type { BkInput } from './motion';
194	+import type { DrInput } from '../drive/motion';
195	+
196	+export interface BkHudNode { classList: { toggle(c: string, on: boolean): unknown } }
197	+export interface BkHudEls { sigL: BkHudNode | null; sigR: BkHudNode | null; stuck: BkHudNode | null; reset: BkHudNode | null }
198	+
199	+const H = CONFIG.bike.hud;
200	+let els: BkHudEls = { sigL: null, sigR: null, stuck: null, reset: null };
201	+let lastSig = 2, lastLit = false, lastStuck = -1;   // 2 / −1: chưa ghi lần nào (lần cập nhật sau bkHudReset luôn ghi)
202	+let hint: HTMLElement | null = null, hintTimer = 0;
203	+
204	+/* Pha nhấp nháy tại thời điểm t (s, shared.uTime): nửa đầu chu kỳ sáng, như model.ts / dash.ts */
205	+export function bkBlinkOn(t: number): boolean { const ph = t * CONFIG.bike.model.sigHz; return ph - Math.floor(ph) < 0.5; }
206	+/* Đã kẹt đủ lâu để nhắc chưa (stuck: s bị chặn mà vẫn vặn ga, motion.ts) */
207	+export function bkStuckOn(stuck: number): boolean { return stuck >= H.stuckS; }
208	+
209	+/* Gắn phần tử (index.ts: từ document; test: phần tử giả) */
210	+export function bkHudBind(e: BkHudEls): void { els = e; }
211	+/* Quên giá trị đã ghi: lần cập nhật sau ghi lại toàn bộ */
212	+export function bkHudReset(): void { lastSig = 2; lastLit = false; lastStuck = -1; }
213	+
214	+const tg = (n: BkHudNode | null, c: string, on: boolean): void => { if (n) n.classList.toggle(c, on); };
215	+
216	+/* Mỗi khung: sig xi nhan (−1 phải / 0 / 1 trái), blink pha sáng (bkBlinkOn), stuck đã kẹt đủ lâu (bkStuckOn) */
217	+export function bkHudUpdate(sig: -1 | 0 | 1, blink: boolean, stuck: boolean): void {
218	+  const lit = sig !== 0 && blink;
219	+  if (sig !== lastSig || lit !== lastLit) {
220	+    lastSig = sig; lastLit = lit;
221	+    tg(els.sigL, 'on', sig === 1); tg(els.sigL, 'lit', sig === 1 && lit);
222	+    tg(els.sigR, 'on', sig === -1); tg(els.sigR, 'lit', sig === -1 && lit);
223	+  }
224	+  const k = stuck ? 1 : 0;
