+const H = CONFIG.bike.hud;
+let els: BkHudEls = { sigL: null, sigR: null, stuck: null, reset: null };
+let lastSig = 2, lastLit = false, lastStuck = -1;   // 2 / −1: chưa ghi lần nào (lần cập nhật sau bkHudReset luôn ghi)
